package dev.infend.skyrimtext;
import org.json.JSONObject;

/** Optional purchased powers, owned and enabled independently in a single game save. */
final class FixShopGifts {
    static final int FATE=0,PHOENIX=1,WARD=2,MENTOR=3,INSURANCE=4,ANCHOR=5,POCKET=6,PURIFY=7,BLOOD=8,TIME=9,AEGIS=10,DRAIN=11,AMBUSH=12,ARCHMAGE=13,ENDURANCE=14,ESCAPE=15,FERRY=16,WIND=17,FORGE=18,BREATH=19,PARDON=20,LOOT=21,BALANCE=22,RESOLVE=23;
    static final String[] NAME={"Благосклонность судьбы","Клятва Феникса","Щит вечной зимы","Эхо древних наставников","Золотой обет","Якорь пространства","Карман Обливиона","Омовение Этериуса","Кровавый обмен","Пески времени","Эгида Этериуса","Похититель жизненной силы","Засада ночного клинка","Пакт архимага","Неутомимый клинок","Тропа призрака","Договор с перевозчиками","Крылья Кинарет","Кузница в ладони","Дыхание Совнгарда","Печать помилования","Сокровища победителя","Равновесие стихий","Печать решимости"};
    static final String[] DESC={"Один повтор неудачной проверки за игровой день. Второй бросок сохраняет исходный шанс.","Один раз в день пережить смертельный удар с 35% здоровья, не завершив бой.","Иммунитет к отравлению и обморожению в обычном бою.","Дополнительные 25% опыта изучаемого навыка при обычной практике, без лишнего опыта героя.","Один раз в день сохранить септимы при поражении. Само поражение остаётся.","Запомнить посещённую точку и вернуться к ней один раз за игровой день.","Доступ к общему хранилищу из любой безопасной локации, без необходимости владеть домом.","Один раз за день восстановить включённые потребности и снять яд и мороз вне боя.","В бою обменять 20% максимального здоровья на 40% максимальной магии один раз за сражение.","Один раз за бой остановить время: противники пропускают ответную атаку, но бой продолжается.","Поглотить до 50 единиц входящего урона при первом попадании в каждом бою.","Восстановить 10% фактического урона обычного или сильного удара, не более 15 здоровья за ход.","Первый успешный удар в каждом бою наносит на 50% больше урона (не более 40 дополнительного урона).","Магическая вспышка расходует на 30% меньше магии.","Сильный удар расходует на 30% меньше выносливости.","Один раз за день гарантированно отступить из обычного боя без трофеев. Не действует в сюжетных и дорожных боях.","Бесплатная переправа между Скайримом и Солстеймом.","Длительность маршрутов сокращается на треть, но минимум один день. Дорожные встречи сохраняются.","Улучшать снаряжение вне кузницы в безопасном месте. Навык и материалы всё ещё необходимы.","Один раз за день восстановить до половины максимального здоровья, магии и выносливости без ожидания.","Один раз за день погасить дорожный штраф в текущем владении, находясь в его столице. Не отменяет другие последствия.","На 25% больше обычной денежной награды за победу над противником. Не действует на мирные сюжетные исходы.","Один раз за бой обменять половину текущей магии на такое же количество выносливости, не превышая максимум.","При защите восстановить дополнительно 10% максимальной выносливости, один раз за бой."};
    static final int[] PRICE={300,650,400,500,250,350,500,300,350,700,550,450,400,450,350,300,250,500,400,350,450,500,350,300};
    static final int ALL=(1<<NAME.length)-1;
    int owned,enabled,fateDay=-1,phoenixDay=-1,insuranceDay=-1,anchorDay=-1,purifyDay=-1;
    boolean bloodUsed=false;
    int battleUsed=0,escapeDay=-1,breathDay=-1,pardonDay=-1;
    boolean availableBattle(int i){return on(i)&&(battleUsed&(1<<i))==0;}
    boolean useBattle(int i){if(!availableBattle(i))return false;battleUsed|=1<<i;return true;}
    int absorb(int damage){return damage>0&&useBattle(AEGIS)?Math.min(50,damage):0;}
    int ambush(int damage){return damage>0&&useBattle(AMBUSH)?Math.min(40,damage/2):0;}
    int drain(int damage,int missing){return on(DRAIN)?Math.min(Math.max(0,missing),Math.min(15,Math.max(0,damage)/10)):0;}
    int cost(int base,int id){return on(id)?Math.max(1,(int)(((long)base*7+9)/10)):base;}
    int fare(int fare){return on(FERRY)?0:fare;}
    int days(int days){return on(WIND)&&days>0?Math.max(1,(int)(((long)days*2+2)/3)):days;}
    int loot(int base){return on(LOOT)?base/4:0;}
    boolean canEscape(GameEngine g){return on(ESCAPE)&&escapeDay!=g.day&&"COMBAT".equals(g.mode)&&"WILD".equals(g.battleKind)&&!g.road.pending();}
    boolean escape(GameEngine g){if(!canEscape(g))return false;escapeDay=g.day;g.mode="RESULT";g.poisonTurns=g.frostTurns=0;g.message="Тропа призрака скрыла тебя от врагов. Ты покидаешь бой без трофеев.";return true;}
    boolean canBalance(GameEngine g){return availableBattle(BALANCE)&&"COMBAT".equals(g.mode)&&g.magicka>=2&&g.stamina<g.maxStamina;}
    boolean balance(GameEngine g){if(!canBalance(g))return false;int n=Math.min(g.magicka/2,g.maxStamina-g.stamina);if(n<=0||!useBattle(BALANCE))return false;g.magicka-=n;g.stamina+=n;return true;}
    boolean breath(GameEngine g){if(!on(BREATH)||breathDay==g.day||!FixShopWorld.safe(g)||(g.hp==g.maxHp&&g.magicka==g.maxMagicka&&g.stamina==g.maxStamina))return false;breathDay=g.day;g.hp=Math.min(g.maxHp,GameEngine.nonnegativeAdd(g.hp,Math.max(1,g.maxHp/2)));g.magicka=Math.min(g.maxMagicka,GameEngine.nonnegativeAdd(g.magicka,Math.max(1,g.maxMagicka/2)));g.stamina=Math.min(g.maxStamina,GameEngine.nonnegativeAdd(g.stamina,Math.max(1,g.maxStamina/2)));g.message="Дыхание Совнгарда восстановило силы.";return true;}
    boolean canPardon(GameEngine g){WorldAtlas.Place p=WorldAtlas.find(g.progress.location);return on(PARDON)&&pardonDay!=g.day&&FixShopWorld.safe(g)&&p!=null&&"Столица".equals(p.type)&&g.road.bounty(p.region)>0;}
    boolean pardon(GameEngine g){if(!canPardon(g)||!g.road.fixPardon(g))return false;pardonDay=g.day;return true;}
    String anchor="";
    boolean owns(int i){return i>=0&&i<NAME.length&&(owned&(1<<i))!=0;}
    boolean on(int i){return owns(i)&&(enabled&(1<<i))!=0;}
    boolean buy(int i){if(i<0||i>=NAME.length||owns(i))return false;owned|=1<<i;enabled|=1<<i;return true;}
    boolean toggle(int i){if(!owns(i))return false;enabled^=1<<i;return true;}
    boolean retry(int day,int chance,int roll){if(!on(FATE)||fateDay==day||chance<=0||chance>=100||roll<=chance)return false;fateDay=day;return true;}
    boolean rescue(GameEngine g){if(!on(PHOENIX)||phoenixDay==g.day||g.hp>0)return false;phoenixDay=g.day;g.hp=Math.max(1,(int)((long)g.maxHp*35/100));g.poisonTurns=g.frostTurns=0;return true;}
    boolean insure(int day){if(!on(INSURANCE)||insuranceDay==day)return false;insuranceDay=day;return true;}
    int skillBonus(int amount){return on(MENTOR)?amount/4:0;}
    boolean mark(GameEngine g){if(!on(ANCHOR)||!FixShopWorld.safe(g)||WorldAtlas.find(g.progress.location)==null||!g.visitedVisual.contains(g.progress.location)||anchor.equals(g.progress.location))return false;anchor=g.progress.location;g.message="Якорь пространства установлен: "+anchor;return true;}
    boolean recall(GameEngine g){if(!on(ANCHOR)||anchorDay==g.day||!FixShopWorld.safe(g)||anchor.isEmpty()||!g.visitedVisual.contains(anchor)||!g.fixTravelToVisited(anchor))return false;anchorDay=g.day;return true;}
    boolean purify(GameEngine g){if(!on(PURIFY)||purifyDay==g.day||!FixShopWorld.safe(g))return false;g.needs.sync(g.day,g.hour);boolean needed=g.poisonTurns>0||g.frostTurns>0;for(int i=0;i<4;i++)needed|=g.needs.enabled(i)&&g.needs.value(i)<100;if(!needed)return false;purifyDay=g.day;g.needs.tavernRest();g.poisonTurns=g.frostTurns=0;g.message="Омовение Этериуса восстановило потребности и сняло яд и мороз.";return true;}
    void beginBattle(){bloodUsed=false;battleUsed=0;}
    boolean canBlood(GameEngine g){return on(BLOOD)&&!bloodUsed&&"COMBAT".equals(g.mode)&&g.hp>Math.max(1,g.maxHp/5)&&g.magicka<g.maxMagicka;}
    boolean blood(GameEngine g){if(!canBlood(g))return false;bloodUsed=true;g.hp-=Math.max(1,g.maxHp/5);g.magicka=(int)Math.min(g.maxMagicka,(long)g.magicka+Math.max(1,(long)g.maxMagicka*2/5));return true;}
    String status(int i,GameEngine g){if(!owns(i))return "Не приобретено";if(!on(i))return "Выключено";int used=i==FATE?fateDay:i==PHOENIX?phoenixDay:i==INSURANCE?insuranceDay:i==ANCHOR?anchorDay:i==PURIFY?purifyDay:i==ESCAPE?escapeDay:i==BREATH?breathDay:i==PARDON?pardonDay:-1;return used==g.day?"Использовано сегодня":i==ANCHOR&&!anchor.isEmpty()?"Якорь: "+anchor:"Активно";}
    static void choices(GameEngine g,GameEngine.Scene s){if(!FixShopWorld.safe(g))return;FixShopGifts f=g.fixShop.gifts;if(f.on(ANCHOR)){if(!f.anchor.equals(g.progress.location)&&g.visitedVisual.contains(g.progress.location))s.add("FIXGIFT:mark","Установить якорь пространства",g.progress.location);if(f.anchorDay!=g.day&&!f.anchor.isEmpty()&&!f.anchor.equals(g.progress.location))s.add("FIXGIFT:recall","Вернуться к якорю",f.anchor);}if(f.on(PURIFY)&&f.purifyDay!=g.day)s.add("FIXGIFT:purify","Омовение Этериуса","Восстановить потребности");if(f.on(BREATH)&&f.breathDay!=g.day&&(g.hp<g.maxHp||g.magicka<g.maxMagicka||g.stamina<g.maxStamina))s.add("FIXGIFT:breath","Дыхание Совнгарда","Восстановить силы");if(f.canPardon(g))s.add("FIXGIFT:pardon","Печать помилования","Погасить местный дорожный штраф");}
    static boolean choose(GameEngine g,String a){FixShopGifts f=g.fixShop.gifts;boolean ok="FIXGIFT:mark".equals(a)?f.mark(g):"FIXGIFT:recall".equals(a)?f.recall(g):"FIXGIFT:breath".equals(a)?f.breath(g):"FIXGIFT:pardon".equals(a)?f.pardon(g):"FIXGIFT:purify".equals(a)&&f.purify(g);if(ok)g.recordVisualEvent(g.message);return ok;}
    JSONObject save(){JSONObject j=new JSONObject();try{j.put("owned",owned).put("enabled",enabled).put("fateDay",fateDay).put("phoenixDay",phoenixDay).put("insuranceDay",insuranceDay).put("anchorDay",anchorDay).put("purifyDay",purifyDay).put("anchor",anchor).put("bloodUsed",bloodUsed).put("battleUsed",battleUsed).put("escapeDay",escapeDay).put("breathDay",breathDay).put("pardonDay",pardonDay);}catch(Exception ignored){}return j;}
    static FixShopGifts restore(JSONObject j){FixShopGifts f=new FixShopGifts();if(j==null)return f;f.owned=j.optInt("owned")&ALL;f.enabled=j.optInt("enabled")&f.owned;f.fateDay=j.optInt("fateDay",-1);f.phoenixDay=j.optInt("phoenixDay",-1);f.insuranceDay=j.optInt("insuranceDay",-1);f.anchorDay=j.optInt("anchorDay",-1);f.purifyDay=j.optInt("purifyDay",-1);String a=j.optString("anchor");if(WorldAtlas.find(a)!=null)f.anchor=a;f.bloodUsed=j.optBoolean("bloodUsed");f.battleUsed=j.optInt("battleUsed")&ALL;f.escapeDay=j.optInt("escapeDay",-1);f.breathDay=j.optInt("breathDay",-1);f.pardonDay=j.optInt("pardonDay",-1);return f;}
}
